DECLARE b ops.pdf_stage_build;
BEGIN
 IF NOT (current_setting('transaction_isolation')=ANY(ARRAY['read committed']::text[])) THEN
 RAISE EXCEPTION 'PDF projection admission requires READ COMMITTED' USING ERRCODE='25000'; END IF;
