-- Immutable section views are instances, never fabricated document/rendition rows.
CREATE OR REPLACE FUNCTION ops.publish_source_view(p_run bigint,p_task bigint,p_attempt bigint,p_holder text,p_position bigint,p_payload bytea,p_recipe bytea) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $view$
DECLARE job ops.task; run ops.run; product jsonb; parsing_item jsonb; projection jsonb; piece jsonb;
 native ops.pdf_selected_product; placement ops.pdf_published_revision; section kb.pdf_record_access; previous kb.source_view; result bigint;
 pos bigint:=0; stop bigint; node jsonb; spelling text; piece_pointer text; expected jsonb; coverage_universe text; local_coverage text; coverage_row record; coverage_rows jsonb;
BEGIN
 SELECT * INTO STRICT run FROM ops.run WHERE id=p_run FOR SHARE;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=p_run FOR UPDATE;
 PERFORM sem.require_execution_operation(run.release_id,'publish_source_view');
 IF job.attempt<>p_attempt OR job.claimed_by IS DISTINCT FROM p_holder THEN RAISE EXCEPTION 'source view attempt lost' USING ERRCODE='P0004'; END IF;
 product:=convert_from(p_payload,'UTF8')::jsonb;
 IF jsonb_typeof(product) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfSourceViewPublication' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(product) key WHERE key<>ALL(ARRAY['key','document_id','native_task_id','native_product_key','native_content_digest','section_pointer','membership','projection_digest','recipe_digest','projection','replaces_source_view_id','analysis_eligible'])) OR NOT (product ? 'key') OR (product ? 'key' AND (jsonb_typeof(product->'key') IS DISTINCT FROM 'string')) OR NOT (product ? 'document_id') OR (product ? 'document_id' AND (jsonb_typeof(product->'document_id') IS DISTINCT FROM 'number' OR product->>'document_id' !~ '^[0-9]+$')) OR (product ? 'document_id' AND (product->>'document_id')::numeric < 1) OR NOT (product ? 'native_task_id') OR (product ? 'native_task_id' AND (jsonb_typeof(product->'native_task_id') IS DISTINCT FROM 'number' OR product->>'native_task_id' !~ '^[0-9]+$')) OR (product ? 'native_task_id' AND (product->>'native_task_id')::numeric < 1) OR NOT (product ? 'native_product_key') OR (product ? 'native_product_key' AND (jsonb_typeof(product->'native_product_key') IS DISTINCT FROM 'string')) OR NOT (product ? 'native_content_digest') OR (product ? 'native_content_digest' AND (jsonb_typeof(product->'native_content_digest') IS DISTINCT FROM 'string')) OR (product ? 'native_content_digest' AND product->>'native_content_digest' !~ '^[0-9a-f]{64}$') OR NOT (product ? 'section_pointer') OR (product ? 'section_pointer' AND (jsonb_typeof(product->'section_pointer') IS DISTINCT FROM 'string')) OR (product ? 'section_pointer' AND product->>'section_pointer' !~ '^#(/[^/]+)+$') OR NOT (product ? 'membership') OR (product ? 'membership' AND (jsonb_typeof(product->'membership') IS DISTINCT FROM 'string' OR product->>'membership' NOT IN ('descendants','direct'))) OR NOT (product ? 'projection_digest') OR (product ? 'projection_digest' AND (jsonb_typeof(product->'projection_digest') IS DISTINCT FROM 'string')) OR (product ? 'projection_digest' AND product->>'projection_digest' !~ '^[0-9a-f]{64}$') OR NOT (product ? 'recipe_digest') OR (pro